    .{ .path = "file_scan_exclusions", .segments = &.{"file_scan_exclusions"}, .page = "search_and_files", .section = "File Scan", .title = "File Scan Exclusions", .description = "Files or globs of files that will be excluded by Zed entirely. They will be skipped during file scans, file searches, and not be displayed in the project file tree. Takes precedence over \\\"File Scan Inclusions\\\"", .default = "[\"**/.git\",\"**/.svn\",\"**/.hg\",\"**/.jj\",\"**/.sl\",\"**/.repo\",\"**/CVS\",\"**/.DS_Store\",\"**/Thumbs.db\",\"**/.classpath\",\"**/.settings\"]" },
    .{ .path = "file_scan_inclusions", .segments = &.{"file_scan_inclusions"}, .page = "search_and_files", .section = "File Scan", .title = "File Scan Inclusions", .description = "Files or globs of files that will be included by Zed, even when ignored by git. This is useful for files that are not tracked by git, but are still important to your project. Note that globs that are overly broad can slow down Zed's file scanning. \\\"File Scan Exclusions\\\" takes precedence over these inclusions", .default = "[\".env*\"]" },
    .{ .path = "file_scan_depth", .segments = &.{"file_scan_depth"}, .page = "search_and_files", .section = "File Scan", .title = "File Scan Depth", .description = "Maximum directory depth to eagerly index outside of git repositories; contents of directories at this depth or deeper are indexed on demand. Repositories rooted shallower than this depth are always indexed fully. In projects that are not rooted at a git repository, repositories directly inside a root folder activate their git features immediately; deeper ones activate on first use. 0 means no limit and activates all git repositories immediately", .default = "5" },
    .{ .path = "scan_symlinks", .segments = &.{"scan_symlinks"}, .page = "search_and_files", .section = "File Scan", .title = "Scan Symbolic Links", .description = "When to scan content of linked directories", .default = "\"expanded\"" },
